# -*- coding: utf-8 -*-from __future__ import annotationsimport argparseimport mathimport osimport warningsfrom functools import partialfrom typing import Callable, Optional, Sequence, Tuple, Unionimport torchimport torch.nn as nnimport torch.nn.functional as F__all__ = [    "RWKV_UNet3D", "RWKV_UNet3D_T", "RWKV_UNet3D_S", "RWKV_UNet3D_B",    "RWKV_UNet_encoder3D", "RWKV_UNet_encoder3D_T", "RWKV_UNet_encoder3D_S",    "RWKV_UNet_encoder3D_B", "build_rwkv_unet3d", "wkv", "wkv_fast", "wkv_exact",    "count_parameters", "inflate_2d_to_3d",]inplace = TrueSizeType = Union[int, Sequence[int]]def to_3tuple(size: SizeType) -> Tuple[int, int, int]:    """``int`` 或 ``(D,H,W)`` -> ``(D,H,W)``。"""    if isinstance(size, int):        return (size, size, size)    size = tuple(int(s) for s in size)    if len(size) == 1:        return (size[0],) * 3    if len(size) != 3:        raise ValueError(f"img_size 需要 int 或 (D, H, W)，收到 {size}")    return size# =====================================================================# 1. 基础组件（3D 版）# =====================================================================class LayerNorm3d(nn.Module):    """在 (B, C, D, H, W) 上做 channel-wise LayerNorm。"""    def __init__(self, normalized_shape, eps=1e-6, elementwise_affine=True):        super().__init__()        self.norm = nn.LayerNorm(normalized_shape, eps, elementwise_affine)    def forward(self, x):        x = x.permute(0, 2, 3, 4, 1).contiguous()  # (B, D, H, W, C)        x = self.norm(x)        return x.permute(0, 4, 1, 2, 3).contiguous()def drop_path(x, drop_prob: float = 0.0, training: bool = False):    if drop_prob == 0.0 or not training:        return x    keep_prob = 1 - drop_prob    shape = (x.shape[0],) + (1,) * (x.ndim - 1)    random_tensor = keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)    random_tensor.floor_()    return x.div(keep_prob) * random_tensorclass DropPath(nn.Module):    def __init__(self, drop_prob: Optional[float] = None):        super().__init__()        self.drop_prob = drop_prob    def forward(self, x):        return drop_path(x, self.drop_prob, self.training)def _no_grad_trunc_normal_(tensor, mean, std, a, b):    def norm_cdf(x):        return (1.0 + math.erf(x / math.sqrt(2.0))) / 2.0    if (mean < a - 2 * std) or (mean > b + 2 * std):        warnings.warn("mean is more than 2 std from [a, b] in nn.init.trunc_normal_.", stacklevel=2)    with torch.no_grad():        l = norm_cdf((a - mean) / std)        u = norm_cdf((b - mean) / std)        tensor.uniform_(2 * l - 1, 2 * u - 1)        tensor.erfinv_()        tensor.mul_(std * math.sqrt(2.0))        tensor.add_(mean)        tensor.clamp_(min=a, max=b)        return tensordef trunc_normal_(tensor, mean=0.0, std=1.0, a=-2.0, b=2.0):    return _no_grad_trunc_normal_(tensor, mean, std, a, b)class GELU(nn.Module):    def __init__(self, inplace: bool = False):        super().__init__()    def forward(self, x):        return F.gelu(x)def get_norm(norm_layer: str = "bn_3d"):    eps = 1e-6    norm_dict = {        "none": nn.Identity,        "in_1d": partial(nn.InstanceNorm1d, eps=eps),        "in_2d": partial(nn.InstanceNorm2d, eps=eps),        "in_3d": partial(nn.InstanceNorm3d, eps=eps),        "bn_1d": partial(nn.BatchNorm1d, eps=eps),        "bn_2d": partial(nn.BatchNorm2d, eps=eps),        "bn_3d": partial(nn.BatchNorm3d, eps=eps),        "gn": partial(nn.GroupNorm, eps=eps),        "ln_1d": partial(nn.LayerNorm, eps=eps),        "ln_2d": partial(LayerNorm3d, eps=eps),  # 兼容 2D 配置名，落到 3D 实现        "ln_3d": partial(LayerNorm3d, eps=eps),    }    return norm_dict[norm_layer]def get_act(act_layer: str = "relu"):    act_dict = {        "none": nn.Identity,        "sigmoid": nn.Sigmoid,        "swish": nn.SiLU,        "silu": nn.SiLU,        "mish": nn.Mish,        "hsigmoid": nn.Hardsigmoid,        "hswish": nn.Hardswish,        "tanh": nn.Tanh,        "relu": nn.ReLU,        "relu6": nn.ReLU6,        "gelu": GELU,    }    return act_dict[act_layer]def make_act(act_layer: str = "relu", inplace: bool = True) -> nn.Module:    act = get_act(act_layer)    try:        return act(inplace=inplace)    except TypeError:        return act()class ConvNormAct(nn.Module):    """3D 版 Conv-Norm-Act。"""    def __init__(self, dim_in, dim_out, kernel_size, stride=1, dilation=1, groups=1,                 bias=False, skip=False, norm_layer="bn_3d", act_layer="relu",                 inplace=True, drop_path_rate=0.0):        super().__init__()        self.has_skip = skip and dim_in == dim_out        padding = math.ceil((kernel_size - stride) / 2)        self.conv = nn.Conv3d(dim_in, dim_out, kernel_size, stride, padding, dilation, groups, bias)        self.norm = get_norm(norm_layer)(dim_out)        self.act = make_act(act_layer, inplace)        self.drop_path = DropPath(drop_path_rate) if drop_path_rate else nn.Identity()    def forward(self, x):        shortcut = x        x = self.conv(x)        x = self.norm(x)        x = self.act(x)        if self.has_skip:            x = self.drop_path(x) + shortcut        return xclass SE(nn.Module):    """Squeeze-and-Excitation（3D：对 D,H,W 做全局平均）。"""    def __init__(self, in_chs: int, rd_ratio: float = 0.25, rd_channels: Optional[int] = None,                 act_layer: Callable = nn.ReLU, gate_layer: Callable = nn.Sigmoid,                 force_act_layer: Optional[Callable] = None,                 rd_round_fn: Optional[Callable] = None):        super().__init__()        if rd_channels is None:            rd_round_fn = rd_round_fn or round            rd_channels = int(rd_round_fn(in_chs * rd_ratio))        act_layer = force_act_layer or act_layer        self.conv_reduce = nn.Conv3d(in_chs, rd_channels, 1, bias=True)        self.act1 = act_layer(inplace=True) if act_layer in (nn.ReLU, nn.SiLU) else act_layer()        self.conv_expand = nn.Conv3d(rd_channels, in_chs, 1, bias=True)        self.gate = gate_layer()    def forward(self, x):        x_se = x.mean((2, 3, 4), keepdim=True)  # (B,C,1,1,1)        x_se = self.conv_reduce(x_se)        x_se = self.act1(x_se)        x_se = self.conv_expand(x_se)        return x * self.gate(x_se)# =====================================================================# 2. WKV# =====================================================================_MIN_VALUE = -1e38_WKV_TOKEN_SPLIT = 32_WKV_EPS = 1e-6def wkv(w, u, k, v):    """加权键值注意力。w、u: (C,)；k、v: (B, T, C)；返回 (B, T, C)。    ``T = D/8 * H/8 * W/8``（stage3 的 token 数）。    ``RWKV_WKV_EXACT=1`` 时使用逐位等价于原版 CUDA kernel 的实现（慢）。    """    if os.environ.get("RWKV_WKV_EXACT", "0") == "1":        return wkv_exact(w, u, k, v)    return wkv_fast(w, u, k, v)def wkv_fast(w, u, k, v, eps: float = _WKV_EPS):    """闭式对称 WKV：        y_i = ( Σ_{j≠i} exp(k_j - w|j-i|) v_j + exp(u+k_i) v_i )              / ( Σ_{j≠i} exp(k_j - w|j-i|)     + exp(u+k_i) + eps )    """    B, T, C = k.shape    dt = torch.float64 if k.dtype == torch.float64 else torch.float32    w = w.to(dt).view(1, 1, C)    u = u.to(dt).view(1, 1, C)    kk = k.to(dt)    vv = v.to(dt)    jw = torch.arange(T, device=k.device, dtype=dt).view(1, T, 1) * w    ek = torch.exp(kk)    def exclusive(c):        return torch.cat([torch.zeros_like(c[:, :1]), c[:, :-1]], dim=1)    def exclusive_from_right(g):        c = torch.cumsum(g, dim=1)        return c[:, -1:] - c    e_p = kk + jw    m_p = e_p.max(dim=1, keepdim=True).values    g_p = torch.exp(e_p - m_p)    pre = torch.exp(m_p - jw)    Pk = exclusive(torch.cumsum(g_p, dim=1)) * pre    Pkv = exclusive(torch.cumsum(g_p * vv, dim=1)) * pre    e_s = kk - jw    m_s = e_s.max(dim=1, keepdim=True).values    g_s = torch.exp(e_s - m_s)    suf = torch.exp(m_s + jw)    Sk = exclusive_from_right(g_s) * suf    Skv = exclusive_from_right(g_s * vv) * suf    eu = torch.exp(u)    num = Pkv + Skv + eu * ek * vv    den = Pk + Sk + eu * ek + eps    return (num / den).to(k.dtype)def wkv_exact(w, u, k, v, eps: float = _WKV_EPS):    """逐位等价于原版 CUDA kernel 的实现（32 token 分块、log-sum-exp 三趟扫描）。"""    B, T, C = k.shape    S = _WKV_TOKEN_SPLIT    L = (T + S - 1) // S    dt = torch.float64 if k.dtype == torch.float64 else torch.float32    w = w.to(dt).view(1, 1, C)    u = u.to(dt).view(1, 1, C)    kk = k.to(dt)    vv = v.to(dt)    t0 = torch.arange(S, device=k.device) * L    lens = (T - t0).clamp(min=0, max=L)    has_b = (lens > 0).view(1, S, 1)    pos_ok = (torch.arange(L, device=k.device).view(L, 1) < lens.view(1, S))    def gather(x, idx):        return x.index_select(1, idx.clamp(0, T - 1))    zeros = torch.zeros(B, S, C, device=k.device, dtype=dt)    mval = torch.full((B, S, C), _MIN_VALUE, device=k.device, dtype=dt)    c_num, c_den, o1 = zeros.clone(), zeros.clone(), mval.clone()    a_num, a_den, o2 = zeros.clone(), zeros.clone(), mval.clone()    for p in range(L):        vm = pos_ok[p].view(1, S, 1)        i = t0 + p        k_i = gather(kk, i)        v_i = gather(vv, i)        arg = k_i - w * p        no = torch.maximum(o1, arg)        e1 = torch.exp(o1 - no)        e3 = torch.exp(arg - no)        c_num = torch.where(vm, e1 * c_num + e3 * v_i, c_num)        c_den = torch.where(vm, e1 * c_den + e3, c_den)        o1 = torch.where(vm, no, o1)        ni = t0 + lens - 1 - p        k_n = gather(kk, ni)        v_n = gather(vv, ni)        arg = k_n - w * (p + 1)        no = torch.maximum(o2, arg)        e2 = torch.exp(o2 - no)        e3 = torch.exp(arg - no)        a_num = torch.where(vm, e2 * a_num + e3 * v_n, a_num)        a_den = torch.where(vm, e2 * a_den + e3, a_den)        o2 = torch.where(vm, no, o2)    Sc, Sd, So1 = c_num, c_den, o1    Sa, Sb, So2 = a_num, a_den, o2    tid = torch.arange(S, device=k.device).view(1, S, 1)    a_num, a_den, o2 = zeros.clone(), zeros.clone(), mval.clone()    for i in range(S):        mk = tid > i        ew = (tid - i - 1) * L        arg = So2[:, i:i + 1, :] - w * ew        no = torch.maximum(arg, o2)        e = torch.exp(o2 - no)        a_num = torch.where(mk, a_num * e + Sa[:, i:i + 1, :] * torch.exp(arg - no), a_num)        a_den = torch.where(mk, a_den * e + Sb[:, i:i + 1, :] * torch.exp(arg - no), a_den)        o2 = torch.where(mk, no, o2)    c_num, c_den, o1 = zeros.clone(), zeros.clone(), mval.clone()    for i in range(S):        mk = tid <= i        ew = (i - tid) * L        arg = So1[:, i:i + 1, :] - w * ew        no = torch.maximum(arg, o1)        e = torch.exp(o1 - no)        c_num = torch.where(mk, c_num * e + Sc[:, i:i + 1, :] * torch.exp(arg - no), c_num)        c_den = torch.where(mk, c_den * e + Sd[:, i:i + 1, :] * torch.exp(arg - no), c_den)        o1 = torch.where(mk, no, o1)    k0 = gather(kk, t0)    v0 = gather(vv, t0)    o1_safe = torch.where(has_b, o1, torch.zeros_like(o1))    sub = torch.exp(k0 - o1_safe)    c_num = torch.where(has_b, c_num - sub * v0, c_num)    c_den = torch.where(has_b, c_den - sub, c_den)    outs = []    for p in range(L):        i = t0 + p        k_i = gather(kk, i)        v_i = gather(vv, i)        no = torch.maximum(o1, u + k_i)        no = torch.maximum(no, o2)        e1 = torch.exp(o1 - no)        e2 = torch.exp(o2 - no)        e3 = torch.exp(u + k_i - no)        outs.append((c_num * e1 + a_num * e2 + e3 * v_i) / (c_den * e1 + a_den * e2 + e3 + eps))        no = torch.maximum(o2 - w, k_i)        e2 = torch.exp(o2 - w - no)        e3 = torch.exp(k_i - no)        a_num = e2 * a_num + e3 * v_i        a_den = e2 * a_den + e3        o2 = no        i2 = (i + 1) % T        k_i2 = gather(kk, i2)        v_i2 = gather(vv, i2)        no = torch.maximum(o1 + w, k_i2 + w)        e1 = torch.exp(o1 + w - no)        e3 = torch.exp(k_i2 + w - no)        c_num = e1 * c_num - e3 * v_i2        c_den = e1 * c_den - e3        o1 = no    y = torch.stack(outs, dim=0)    y = y.permute(1, 2, 0, 3).reshape(B, S * L, C)    return y[:, :T].to(k.dtype)def q_shift3d(x, shift_pixel: int = 1, gamma: float = 1 / 6, patch_resolution=None):    """3D 版邻域平移：把通道分成 6 组，分别沿 W±、H±、D± 方向平移。    对应 2D 版 ``q_shift``（4 组：左右上下）。``gamma=1/6``。    """    assert gamma <= 1 / 6, "3D 版最多用到 6 组通道"    B, N, C = x.shape    D, H, W = patch_resolution    input = x.transpose(1, 2).reshape(B, C, D, H, W)    output = x.new_zeros(input.shape)    g1, g2 = int(C * gamma), int(C * gamma * 2)    g3, g4 = int(C * gamma * 3), int(C * gamma * 4)    g5, g6 = int(C * gamma * 5), int(C * gamma * 6)    # 沿 W 方向    output[:, 0:g1, :, :, shift_pixel:W] = input[:, 0:g1, :, :, 0:W - shift_pixel]    output[:, g1:g2, :, :, 0:W - shift_pixel] = input[:, g1:g2, :, :, shift_pixel:W]    # 沿 H 方向    output[:, g2:g3, :, shift_pixel:H, :] = input[:, g2:g3, :, 0:H - shift_pixel, :]    output[:, g3:g4, :, 0:H - shift_pixel, :] = input[:, g3:g4, :, shift_pixel:H, :]    # 沿 D 方向    output[:, g4:g5, shift_pixel:D, :, :] = input[:, g4:g5, 0:D - shift_pixel, :, :]    output[:, g5:g6, 0:D - shift_pixel, :, :] = input[:, g5:g6, shift_pixel:D, :, :]    # 剩下的通道不平移    output[:, g6:, ...] = input[:, g6:, ...]    return output.flatten(2).transpose(1, 2)def q_shift2d(x, shift_pixel: int = 1, gamma: float = 1 / 4, patch_resolution=None):    """2D 版邻域平移（4 组：左右上下），用于 ``depth_mode="slice"``：逐层做 2D 注意力。    与 2D 版 RWKV-UNet 的 ``q_shift`` 完全一致，因此 2D 预训练的注意力权重可以照搬。    """    assert gamma <= 1 / 4    B, N, C = x.shape    H, W = patch_resolution    input = x.transpose(1, 2).reshape(B, C, H, W)    output = x.new_zeros(input.shape)    g1, g2, g3, g4 = int(C * gamma), int(C * gamma * 2), int(C * gamma * 3), int(C * gamma * 4)    output[:, 0:g1, :, shift_pixel:W] = input[:, 0:g1, :, 0:W - shift_pixel]    output[:, g1:g2, :, 0:W - shift_pixel] = input[:, g1:g2, :, shift_pixel:W]    output[:, g2:g3, shift_pixel:H, :] = input[:, g2:g3, 0:H - shift_pixel, :]    output[:, g3:g4, 0:H - shift_pixel, :] = input[:, g3:g4, shift_pixel:H, :]    output[:, g4:, ...] = input[:, g4:, ...]    return output.flatten(2).transpose(1, 2)# =====================================================================# 3. RWKV 空间混合 / 通道混合 / 跨尺度融合（3D）# =====================================================================class VRWKV_SpatialMix(nn.Module):    """RWKV 空间混合。    ``mode="full"``：把整个 ``D*H*W`` 展平成一条序列做双向衰减注意力（默认）；    ``mode="slice"``：逐层（每个 D 切片）做 2D 注意力，``T = H*W``，深度方向靠 3D 卷积融合。    后者与 2D 版的行为/权重语义一致，体数据深度不大或要复用 2D 预训练时更稳。    """    def __init__(self, n_embd, channel_gamma=1 / 6, shift_pixel=1, mode="full"):        super().__init__()        self.n_embd = n_embd        self.mode = mode        attn_sz = n_embd        self._init_weights()        self.shift_pixel = shift_pixel        if shift_pixel > 0:            self.channel_gamma = 1 / 4 if mode == "slice" else channel_gamma        else:            self.spatial_mix_k = None            self.spatial_mix_v = None            self.spatial_mix_r = None        self.key = nn.Linear(n_embd, attn_sz, bias=False)        self.value = nn.Linear(n_embd, attn_sz, bias=False)        self.receptance = nn.Linear(n_embd, attn_sz, bias=False)        self.key_norm = nn.LayerNorm(n_embd)        self.output = nn.Linear(attn_sz, n_embd, bias=False)    def _init_weights(self):        self.spatial_decay = nn.Parameter(torch.zeros(self.n_embd))        self.spatial_first = nn.Parameter(torch.zeros(self.n_embd))        self.spatial_mix_k = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)        self.spatial_mix_v = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)        self.spatial_mix_r = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)    def jit_func(self, x, patch_resolution):        if self.shift_pixel > 0:            shift = q_shift2d if self.mode == "slice" else q_shift3d            xx = shift(x, self.shift_pixel, self.channel_gamma, patch_resolution)            xk = x * self.spatial_mix_k + xx * (1 - self.spatial_mix_k)            xv = x * self.spatial_mix_v + xx * (1 - self.spatial_mix_v)            xr = x * self.spatial_mix_r + xx * (1 - self.spatial_mix_r)        else:            xk = xv = xr = x        k = self.key(xk)        v = self.value(xv)        r = self.receptance(xr)        return torch.sigmoid(r), k, v    def forward(self, x, patch_resolution=None):        B, T, C = x.size()        sr, k, v = self.jit_func(x, patch_resolution)        x = wkv(self.spatial_decay / T, self.spatial_first / T, k, v)        x = self.key_norm(x)        x = sr * x        return self.output(x)def _wkv_along_axis(w, u, k, v, axis):    """在 (B, D, H, W, C) 上沿 ``axis``（0=D, 1=H, 2=W）建序列做 WKV，返回同形状。"""    B, D, H, W, C = k.shape    if axis == 2:  # 沿 W：每个 (d,h) 一条序列        kk = k.reshape(B * D * H, W, C)        vv = v.reshape(B * D * H, W, C)        return wkv(w, u, kk, vv).view(B, D, H, W, C)    if axis == 1:  # 沿 H：每个 (d,w) 一条序列        kk = k.permute(0, 1, 3, 2, 4).reshape(B * D * W, H, C)        vv = v.permute(0, 1, 3, 2, 4).reshape(B * D * W, H, C)        y = wkv(w, u, kk, vv).view(B, D, W, H, C)        return y.permute(0, 1, 3, 2, 4)    if axis == 0:  # 沿 D：每个 (h,w) 一条序列        kk = k.permute(0, 2, 3, 1, 4).reshape(B * H * W, D, C)        vv = v.permute(0, 2, 3, 1, 4).reshape(B * H * W, D, C)        y = wkv(w, u, kk, vv).view(B, H, W, D, C)        return y.permute(0, 3, 1, 2, 4)    raise ValueError(f"axis 只能是 0/1/2，收到 {axis}")class VRWKV_TriSpatialMix(nn.Module):    """U-RWKV 论文里的 **TSE-R**（Tri-directional Spatial Enhancement RWKV）。    两个针对 3D 的改动（对应论文摘要）：    1. **spatial-shift**：进入 WKV 前先做 6 方向邻域平移（``q_shift3d``），把相邻体素       的信息混进来，缓解"把体数据串成一条序列"造成的结构信息丢失；    2. **tri-directional scanning**：分别沿 D、H、W 三个方向把体素串成序列，各做一次       WKV（每次复杂度仍是 O(T)），最后用 **可学习权重** 融合（softmax 归一化，       初始化时三个方向等权）。    这样深度方向的交互不再依赖"D·H·W 展平后相邻层相距 H·W"这种病态距离，而是各自    沿轴扫描，结构信息保留得更好。    """    def __init__(self, n_embd, channel_gamma=1 / 6, shift_pixel=1):        super().__init__()        self.n_embd = n_embd        self._init_weights()        self.shift_pixel = shift_pixel        self.channel_gamma = channel_gamma        self.key = nn.Linear(n_embd, n_embd, bias=False)        self.value = nn.Linear(n_embd, n_embd, bias=False)        self.receptance = nn.Linear(n_embd, n_embd, bias=False)        self.key_norm = nn.LayerNorm(n_embd)        self.output = nn.Linear(n_embd, n_embd, bias=False)        # 三方向融合权重（softmax 后使用，初始 1/3、1/3、1/3）        self.dir_logits = nn.Parameter(torch.zeros(3))    def _init_weights(self):        self.spatial_decay = nn.Parameter(torch.zeros(self.n_embd))        self.spatial_first = nn.Parameter(torch.zeros(self.n_embd))        self.spatial_mix_k = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)        self.spatial_mix_v = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)        self.spatial_mix_r = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)    def jit_func(self, x, patch_resolution):        if self.shift_pixel > 0:            xx = q_shift3d(x, self.shift_pixel, self.channel_gamma, patch_resolution)            xk = x * self.spatial_mix_k + xx * (1 - self.spatial_mix_k)            xv = x * self.spatial_mix_v + xx * (1 - self.spatial_mix_v)            xr = x * self.spatial_mix_r + xx * (1 - self.spatial_mix_r)        else:            xk = xv = xr = x        return torch.sigmoid(self.receptance(xr)), self.key(xk), self.value(xv)    def forward(self, x, patch_resolution=None):        B, N, C = x.size()        D, H, W = patch_resolution        sr, k, v = self.jit_func(x, patch_resolution)  # (B, D*H*W, C)        k5 = k.view(B, D, H, W, C)        v5 = v.view(B, D, H, W, C)        outs = []        for axis, length in ((0, D), (1, H), (2, W)):  # 每个方向按该轴长度归一化衰减            outs.append(_wkv_along_axis(self.spatial_decay / length,                                        self.spatial_first / length, k5, v5, axis))        weights = torch.softmax(self.dir_logits, dim=0)  # (3,) 可学习融合        y = weights[0] * outs[0] + weights[1] * outs[1] + weights[2] * outs[2]        y = y.reshape(B, N, C)        y = self.key_norm(y)        return self.output(sr * y)class VRWKV_ChannelMix(nn.Module):    def __init__(self, n_embd, channel_gamma=1 / 6, shift_pixel=1, hidden_rate=2, key_norm=True,                 mode="full"):        super().__init__()        self.n_embd = n_embd        self.mode = mode        self._init_weights()        self.shift_pixel = shift_pixel        if shift_pixel > 0:            self.channel_gamma = 1 / 4 if mode == "slice" else channel_gamma        else:            self.spatial_mix_k = None            self.spatial_mix_r = None        hidden_sz = hidden_rate * n_embd        self.key = nn.Linear(n_embd, hidden_sz, bias=False)        self.key_norm = nn.LayerNorm(hidden_sz) if key_norm else None        self.receptance = nn.Linear(n_embd, n_embd, bias=False)        self.value = nn.Linear(hidden_sz, n_embd, bias=False)    def _init_weights(self):        self.spatial_mix_k = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)        self.spatial_mix_r = nn.Parameter(torch.ones([1, 1, self.n_embd]) * 0.5)    def forward(self, x, patch_resolution=None):        if self.shift_pixel > 0:            shift = q_shift2d if self.mode == "slice" else q_shift3d            xx = shift(x, self.shift_pixel, self.channel_gamma, patch_resolution)            xk = x * self.spatial_mix_k + xx * (1 - self.spatial_mix_k)            xr = x * self.spatial_mix_r + xx * (1 - self.spatial_mix_r)        else:            xk = xr = x        k = self.key(xk)        k = torch.square(torch.relu(k))        if self.key_norm is not None:            k = self.key_norm(k)        kv = self.value(k)        return torch.sigmoid(self.receptance(xr)) * kvclass CCMix(nn.Module):    """3D 版 Cross-scale Channel Mix：把三个尺度的特征三线性对齐后做通道混合。    ``depth_mode="slice"`` 时按层（2D）做通道混合，保持和 2D 预训练权重一致的语义。    """    def __init__(self, in_dims, target_dim, target_size: Tuple[int, int, int], drop_path_rate=0.05,                 depth_mode="full"):        super().__init__()        self.target_dim = target_dim        self.target_size = tuple(target_size)        self.depth_mode = depth_mode        self.projections = nn.ModuleList([nn.Conv3d(in_dim, target_dim, kernel_size=1) for in_dim in in_dims])        self.ln1 = nn.LayerNorm(target_dim * 3)        self.drop_path = DropPath(drop_path_rate) if drop_path_rate else nn.Identity()        self.channel = VRWKV_ChannelMix(n_embd=target_dim * 3, channel_gamma=1 / 6, shift_pixel=1,                                        hidden_rate=2, mode=depth_mode)        self.final_projections = nn.ModuleList([nn.Conv3d(target_dim, in_dim, kernel_size=1) for in_dim in in_dims])        d, h, w = self.target_size        self.original_sizes = [(d // 4, h // 4, w // 4), (d // 2, h // 2, w // 2), (d, h, w)]    def forward(self, features):        upsampled = []        outputs = []        for i, feature in enumerate(features):            feature = F.interpolate(feature, size=self.target_size, mode="trilinear", align_corners=False)            upsampled.append(self.projections[i](feature))        concatenated = torch.cat(upsampled, dim=1)  # (B, 3*C, D, H, W)        B, C = concatenated.shape[:2]        D, H, W = self.target_size        if self.depth_mode == "slice":            # (B, C, D, H, W) -> (B*D, H*W, C)，逐层做 2D 通道混合            seq = concatenated.permute(0, 2, 1, 3, 4).reshape(B * D, C, H * W).permute(0, 2, 1)            seq = seq + self.drop_path(self.ln1(self.channel(seq, (H, W))))            merged = seq.permute(0, 2, 1).reshape(B, D, C, H, W).permute(0, 2, 1, 3, 4).contiguous()        else:            seq = concatenated.view(B, C, -1).permute(0, 2, 1)  # (B, N, C)            seq = seq + self.drop_path(self.ln1(self.channel(seq, self.target_size)))            merged = seq.permute(0, 2, 1).contiguous().view(B, C, D, H, W)        for i, split_feature in enumerate(torch.split(merged, self.target_dim, dim=1)):            split_feature = self.final_projections[i](split_feature)            split_feature = F.interpolate(split_feature, size=self.original_sizes[i],                                          mode="trilinear", align_corners=False)            outputs.append(split_feature)        return outputs# =====================================================================# 4. GLSP 块与编码器（3D）# =====================================================================class GLSP(nn.Module):    """Global-Local Spatial Perception block（3D）：卷积做局部建模，WKV 做长程建模。"""    def __init__(self, dim_in, dim_out, norm_in=True, has_skip=True, exp_ratio=1.0,                 norm_layer="bn_3d", act_layer="relu", dw_ks=3, stride=1, dilation=1,                 se_ratio=0.0, attn_s=True, drop_path=0.0, drop=0.0, img_size=(64, 128, 128),                 channel_gamma=1 / 6, shift_pixel=1, depth_mode="full"):        super().__init__()        self.depth_mode = depth_mode        self.norm = get_norm(norm_layer)(dim_in) if norm_in else nn.Identity()        dim_mid = int(dim_in * exp_ratio)        self.ln1 = nn.LayerNorm(dim_mid)        self.ln2 = nn.LayerNorm(dim_mid)        self.conv = ConvNormAct(dim_in, dim_mid, kernel_size=1)        self.has_skip = (dim_in == dim_out and stride == 1) and has_skip        self.att = (VRWKV_TriSpatialMix(dim_mid, channel_gamma, shift_pixel)                    if depth_mode == "tri"                    else VRWKV_SpatialMix(dim_mid, channel_gamma, shift_pixel, mode=depth_mode))        self.se = SE(dim_mid, rd_ratio=se_ratio, act_layer=get_act(act_layer)) if se_ratio > 0.0 else nn.Identity()        self.proj_drop = nn.Dropout(drop)        self.proj = ConvNormAct(dim_mid, dim_out, kernel_size=1, norm_layer="none",                                act_layer="none", inplace=inplace)        self.drop_path = DropPath(drop_path) if drop_path else nn.Identity()        self.attn_s = attn_s        self.conv_local = ConvNormAct(dim_mid, dim_mid, kernel_size=dw_ks, stride=stride,                                      dilation=dilation, groups=dim_mid, norm_layer="bn_3d",                                      act_layer="silu", inplace=inplace)        self.drop_after_pos = nn.Dropout(p=0.1)        self.num_extra_tokens = 0        self.grad_checkpointing = False    def forward(self, x):        if self.grad_checkpointing and self.training:            from torch.utils.checkpoint import checkpoint            return checkpoint(self._forward, x, use_reentrant=False)        return self._forward(x)    def _forward(self, x):        shortcut = x        x = self.norm(x)        x = self.conv(x)        if self.attn_s:            B, hidden, D, H, W = x.size()            if self.depth_mode == "slice":                # 逐层 2D 注意力：把 D 折进 batch，T = H*W                seq = x.permute(0, 2, 1, 3, 4).reshape(B * D, hidden, H * W).permute(0, 2, 1)                seq = seq + self.drop_path(self.ln1(self.att(seq, (H, W))))                x = seq.permute(0, 2, 1).reshape(B, D, hidden, H, W).permute(0, 2, 1, 3, 4).contiguous()            else:                seq = x.view(B, hidden, -1).permute(0, 2, 1)  # (B, N, C)                seq = seq + self.drop_path(self.ln1(self.att(seq, (D, H, W))))                x = seq.permute(0, 2, 1).contiguous().view(B, hidden, D, H, W)        x = x + self.se(self.conv_local(x)) if self.has_skip else self.se(self.conv_local(x))        x = self.proj_drop(x)        x = self.proj(x)        x = (shortcut + self.drop_path(x)) if self.has_skip else x        return xclass RWKV_UNet_encoder3D(nn.Module):    """四阶段金字塔 3D 编码器（stage0 是 stem，stride=1）。"""    def __init__(self, dim_in=3, num_classes=1000, img_size=(64, 128, 128),                 depths=(2, 4, 4, 2), stem_dim=16, embed_dims=(64, 128, 256, 512),                 exp_ratios=(2.0, 2.0, 4.0, 4.0),                 norm_layers=("bn_3d", "bn_3d", "bn_3d", "bn_3d"),                 act_layers=("relu", "relu", "relu", "relu"),                 dw_kss=(3, 3, 1, 1), se_ratios=(0.0, 0.0, 0.0, 0.0),                 attn_ss=(False, False, True, True), drop=0.0, drop_path=0.0,                 pre_dim=0, channel_gamma=1 / 6, shift_pixel=1, depth_mode="full"):        super().__init__()        self.num_classes = num_classes        assert num_classes > 0        dprs = [x.item() for x in torch.linspace(0, drop_path, sum(depths))]        self.embed_dims = list(embed_dims)        self.depth_mode = depth_mode        img_size = to_3tuple(img_size)        self.stage0 = nn.ModuleList([            GLSP(dim_in, stem_dim, norm_in=False, has_skip=False, exp_ratio=1,                 norm_layer=norm_layers[0], act_layer=act_layers[0], dw_ks=dw_kss[0],                 stride=1, dilation=1, se_ratio=1, attn_s=False,                 drop_path=0.0, drop=0.0, img_size=img_size, depth_mode=depth_mode)        ])        emb_dim_pre = stem_dim        for i in range(len(depths)):            layers = []            dpr = dprs[sum(depths[:i]):sum(depths[:i + 1])]            for j in range(depths[i]):                if j == 0:                    stride, has_skip, attn_s, exp_ratio = 2, False, False, exp_ratios[i] * 2                else:                    stride, has_skip, attn_s, exp_ratio = 1, True, attn_ss[i], exp_ratios[i]                layers.append(GLSP(                    emb_dim_pre, embed_dims[i], norm_in=True, has_skip=has_skip,                    exp_ratio=exp_ratio, norm_layer=norm_layers[i],                    act_layer=act_layers[i], dw_ks=dw_kss[i], stride=stride, dilation=1,                    se_ratio=se_ratios[i], attn_s=attn_s, drop_path=dpr[j], drop=drop,                    img_size=img_size, channel_gamma=channel_gamma, shift_pixel=shift_pixel,                    depth_mode=depth_mode,                ))                emb_dim_pre = embed_dims[i]            self.__setattr__(f"stage{i + 1}", nn.ModuleList(layers))        self.pre_dim = embed_dims[-1]        self.norm = get_norm(norm_layers[-1])(embed_dims[-1])        self.head = nn.Linear(self.pre_dim, num_classes)        self.apply(self._init_weights)    def _init_weights(self, m):        if isinstance(m, nn.Linear):            trunc_normal_(m.weight, std=0.02)            if m.bias is not None:                nn.init.zeros_(m.bias)        elif isinstance(m, (nn.LayerNorm, nn.GroupNorm,                            nn.BatchNorm1d, nn.BatchNorm2d, nn.BatchNorm3d,                            nn.InstanceNorm1d, nn.InstanceNorm2d, nn.InstanceNorm3d)):            # InstanceNorm 默认 affine=False，没有 weight/bias，要判空            if getattr(m, "weight", None) is not None:                nn.init.ones_(m.weight)            if getattr(m, "bias", None) is not None:                nn.init.zeros_(m.bias)    @torch.jit.ignore    def no_weight_decay(self):        return {"token"}    def check_bn(self):        for _, m in self.named_modules():            if isinstance(m, nn.modules.batchnorm._NormBase):                m.running_mean = torch.nan_to_num(m.running_mean, nan=0, posinf=1, neginf=-1)                m.running_var = torch.nan_to_num(m.running_var, nan=0, posinf=1, neginf=-1)    def forward_features(self, x):        for blk in self.stage0:            x = blk(x)        for blk in self.stage1:            x = blk(x)        for blk in self.stage2:            x = blk(x)        for blk in self.stage3:            x = blk(x)        for blk in self.stage4:            x = blk(x)        return x    def forward(self, x):        return self.forward_features(x)def _encoder(depths, stem_dim, embed_dims, exp_ratios, norm3d="bn_3d", depth_mode="full", **kwargs):    return RWKV_UNet_encoder3D(        depths=depths, stem_dim=stem_dim, embed_dims=embed_dims, exp_ratios=exp_ratios,        norm_layers=[norm3d, norm3d, "ln_3d", "ln_3d"],        act_layers=["silu", "silu", "gelu", "gelu"], dw_kss=[5, 5, 5, 5],        attn_ss=[False, False, True, True], drop=0.0, drop_path=0.05,        depth_mode=depth_mode, **kwargs)def RWKV_UNet_encoder3D_T(pretrained=False, **kwargs):    return _encoder([2, 2, 4, 2], 24, [32, 48, 96, 160], [2.0, 2.5, 3.0, 3.5], **kwargs)def RWKV_UNet_encoder3D_S(pretrained=False, **kwargs):    return _encoder([3, 3, 6, 3], 24, [32, 64, 128, 192], [2.0, 2.5, 3.0, 4.0], **kwargs)def RWKV_UNet_encoder3D_B(pretrained=False, **kwargs):    return _encoder([3, 3, 6, 3], 24, [48, 72, 144, 240], [2.0, 2.5, 4.0, 4.0], **kwargs)# =====================================================================# 5. 解码器与完整 3D 网络# =====================================================================class UpBlock(nn.Module):    """3D 解码器基本块：1x1 升降维 + 深度可分离 3D 卷积 + 三线性上采样。"""    def __init__(self, dim_in, dim_out, norm_in=False, has_skip=False, exp_ratio=1.0,                 norm_layer="bn_3d", dw_ks=3, stride=1, dilation=1, se_ratio=0.0,                 drop_path=0.0, drop=0.0, act_layer="relu"):        super().__init__()        self.has_skip = has_skip        self.norm = get_norm(norm_layer)(dim_in) if norm_in else nn.Identity()        dim_mid = int(dim_in * exp_ratio)        self.ln1 = nn.LayerNorm(dim_mid)        self.conv = ConvNormAct(dim_in, dim_mid, kernel_size=1)        self.se = SE(dim_mid, rd_ratio=se_ratio, act_layer=get_act(act_layer)) if se_ratio > 0.0 else nn.Identity()        self.proj_drop = nn.Dropout(drop)        self.proj = ConvNormAct(dim_mid, dim_out, kernel_size=1, norm_layer="bn_3d",                                act_layer="relu", inplace=inplace)        self.drop_path = DropPath(drop_path) if drop_path else nn.Identity()        self.conv_local = ConvNormAct(dim_mid, dim_mid, kernel_size=dw_ks, stride=stride,                                      dilation=dilation, groups=dim_mid, norm_layer="bn_3d",                                      act_layer="silu", inplace=inplace)        self.upsample = nn.Upsample(scale_factor=2, mode="trilinear")        self.grad_checkpointing = False    def forward(self, x):        if self.grad_checkpointing and self.training:            from torch.utils.checkpoint import checkpoint            return checkpoint(self._forward, x, use_reentrant=False)        return self._forward(x)    def _forward(self, x):        x = self.norm(x)        x = self.conv(x)        x = x + self.se(self.conv_local(x)) if self.has_skip else self.se(self.conv_local(x))        x = self.proj(x)        x = self.proj_drop(x)        return self.upsample(x)class _RWKVUNet3DBase(nn.Module):    """三种规模共用的 3D 骨架。"""    encoder_factory: Callable = staticmethod(RWKV_UNet_encoder3D_B)    embed_dims: tuple = (48, 72, 144, 240)    def __init__(self, in_channels=1, num_classes=9, img_size=(64, 128, 128), pretrained_path=None,                 depth_mode="full", norm3d="bn_3d"):        super().__init__()        self.size = to_3tuple(img_size)        for s in self.size:            if s % 16 != 0:                raise ValueError(f"img_size 的每个维度都必须是 16 的倍数（编码器 4 次下采样），收到 {self.size}")        self.in_channels = in_channels        self.num_classes = num_classes        self.img_size = tuple(self.size)        self.depth_mode = depth_mode        self.norm3d = norm3d        self.embed_dims = list(self.embed_dims)        self.encoder = self.encoder_factory(img_size=self.size, depth_mode=depth_mode, norm3d=norm3d)        if pretrained_path:            self._load_encoder_weights(pretrained_path)        # CCMix 的目标尺寸 = 编码器 stage0 输出的空间尺寸 = 输入 / 2        target = tuple(s // 2 for s in self.size)        self.ccm = CCMix([self.embed_dims[2], self.embed_dims[1], self.embed_dims[0]],                         self.embed_dims[0], target, depth_mode=depth_mode)        self.decoder1 = UpBlock(self.embed_dims[3], self.embed_dims[2], dw_ks=9, se_ratio=0.0)        self.decoder2 = UpBlock(self.embed_dims[2] * 2, self.embed_dims[1], dw_ks=9, se_ratio=0.0)        self.decoder3 = UpBlock(self.embed_dims[1] * 2, self.embed_dims[0], dw_ks=9, se_ratio=0.0)        self.decoder4 = UpBlock(self.embed_dims[0] * 2, 24, dw_ks=9, se_ratio=0.0)        self.final_conv = nn.Conv3d(24, num_classes, kernel_size=1)    def _load_encoder_weights(self, path):        if not os.path.exists(path):            warnings.warn(f"找不到权重 {path}，encoder 将随机初始化。")            return        state = torch.load(path, map_location="cpu")        if isinstance(state, dict):            state = state.get("state_dict", state.get("model", state))        prefix = "encoder."        if any(k.startswith(prefix) for k in state):            state = {k[len(prefix):]: v for k, v in state.items() if k.startswith(prefix)}        missing, unexpected = self.encoder.load_state_dict(state, strict=False)        if missing or unexpected:            warnings.warn(f"encoder 权重部分加载：missing={len(missing)}, unexpected={len(unexpected)}")    def _prepare_input(self, x):        if x.dim() != 5:            raise ValueError(f"3D 版期望 5D 输入 (B, C, D, H, W)，实际得到 {tuple(x.shape)}")        c = x.shape[1]        if c == 3:            return x        if c == 1:            return x.repeat(1, 3, 1, 1, 1)        raise ValueError(f"in_channels 只支持 1 或 3，实际得到 {c}")    def forward_features(self, x):        x = self._prepare_input(x)        for blk in self.encoder.stage0:            x = blk(x)        enc0 = x        for blk in self.encoder.stage1:            x = blk(x)        enc1 = x        for blk in self.encoder.stage2:            x = blk(x)        enc2 = x        for blk in self.encoder.stage3:            x = blk(x)        enc3 = x        for blk in self.encoder.stage4:            x = blk(x)        enc3, enc2, enc1 = self.ccm([enc3, enc2, enc1])        return x, enc1, enc2, enc3    def forward(self, x):        """返回分割 logits，形状 (B, num_classes, D, H, W)。"""        x, enc1, enc2, enc3 = self.forward_features(x)        dec3 = self.decoder1(x)        dec2 = self.decoder2(torch.cat([dec3, enc3], dim=1))        dec1 = self.decoder3(torch.cat([dec2, enc2], dim=1))        dec0 = self.decoder4(torch.cat([dec1, enc1], dim=1))        out_logit = self.final_conv(dec0)        if self.num_classes == 1:            output = torch.sigmoid(out_logit)        if self.num_classes > 1:            output = torch.softmax(out_logit, dim=1)        return out_logit, outputclass RWKV_UNet3D(_RWKVUNet3DBase):    """Base 规模。"""    encoder_factory = staticmethod(RWKV_UNet_encoder3D_B)    embed_dims = (48, 72, 144, 240)class RWKV_UNet3D_S(_RWKVUNet3DBase):    """Small 规模。"""    encoder_factory = staticmethod(RWKV_UNet_encoder3D_S)    embed_dims = (32, 64, 128, 192)class RWKV_UNet3D_T(_RWKVUNet3DBase):    """Tiny 规模（小体数据、快验证用）。"""    encoder_factory = staticmethod(RWKV_UNet_encoder3D_T)    embed_dims = (32, 48, 96, 160)    def __init__(self, in_channels=1, num_classes=1, img_size=(64, 128, 128), pretrained_path=None,                 depth_mode="full", norm3d="bn_3d"):        super().__init__(in_channels=in_channels, num_classes=num_classes,                         img_size=img_size, pretrained_path=pretrained_path,                         depth_mode=depth_mode, norm3d=norm3d)RWKV_UNet3D_B = RWKV_UNet3Ddef build_rwkv_unet3d(model: str = "B", in_channels: int = 1, num_classes: int = 9,                      img_size: SizeType = (64, 128, 128), pretrained_path: Optional[str] = None,                      **kwargs):    """按名字建 3D 模型：model ∈ {'T', 'S', 'B'}。"""    table = {"t": RWKV_UNet3D_T, "s": RWKV_UNet3D_S, "b": RWKV_UNet3D}    key = str(model).lower()    if key not in table:        raise ValueError(f"未知模型规模 {model!r}，可选 'T' / 'S' / 'B'")    return table[key](in_channels=in_channels, num_classes=num_classes,                      img_size=img_size, pretrained_path=pretrained_path, **kwargs)def count_parameters(module: nn.Module, trainable_only: bool = True) -> int:    return sum(p.numel() for p in module.parameters() if (p.requires_grad or not trainable_only))def enable_gradient_checkpointing(model: nn.Module, enabled: bool = True) -> nn.Module:    """对 ``GLSP`` / ``UpBlock`` 打开梯度检查点（用时间换显存，约减半）。    打开后前向不保存中间激活，反向时重新算一遍：显存通常降 40–50%，单步时间 +20~30%。    """    n = 0    for m in model.modules():        if isinstance(m, (GLSP, UpBlock)):            m.grad_checkpointing = enabled            n += 1    if hasattr(model, "grad_checkpointing"):        model.grad_checkpointing = enabled    return model# =====================================================================# 6. 用 2D 权重“膨胀”出 3D 初始化（可选，用于在 2D 预训练模型上热启动）# =====================================================================def inflate_2d_to_3d(state2d: dict, model3d: nn.Module, mode: str = "repeat",                     verbose: bool = True) -> nn.Module:    """把 2D 版 ``RWKV_UNet`` 的 ``state_dict`` 膨胀成 3D 模型的初始化。    * 4D 卷积核 ``(O, I, kh, kw)`` -> ``(O, I, kd, kh, kw)``：      ``mode="repeat"``（默认，I3D 式）沿 D 复制 ``kd`` 份再除以 ``kd``，保持对      沿 D 恒定输入的响应量级不变；``mode="center"`` 只填中间一层、其余补零。    * 1x1 卷积 ``(O, I, 1, 1)`` -> ``(O, I, 1, 1, 1)``，等价。    * BN / LayerNorm / Linear 的形状与维度无关，直接照搬。    两种键名前缀都支持：完整模型 ``encoder.stage0...`` 或只存 encoder 的 ``stage0...``。    如果一个都匹配不上会直接报错（避免"以为加载了、其实没加载"）。    注意：这只是**热启动**，不是数值等价。WKV 的序列长度、上采样方式、CCMix 插值都会让    输出与 2D 不同；``depth_mode="slice"`` 时最接近 2D（实测 corr 0.99997）。    """    sd3 = model3d.state_dict()    # ---- 自动适配键名前缀：完整模型 vs 只存 encoder    keys = list(state2d.keys())    n_prefixed = sum(1 for k in keys if k in sd3)    if n_prefixed == 0:        trial = {"encoder." + k: v for k, v in state2d.items()}        n_trial = sum(1 for k in trial if k in sd3)        if n_trial > 0:            state2d = trial            if verbose:                print(f"[inflate] 检测到 encoder-only 权重，自动补 'encoder.' 前缀（匹配 {n_trial} 项）")        else:            raise ValueError(                "inflate_2d_to_3d: 没有任何键能对上 3D 模型。\n"                f"  2D 权重前 3 个键: {keys[:3]}\n"                f"  3D 模型前 3 个键: {list(sd3)[:3]}\n"                "  可能原因：加载的不是 RWKV_UNet 的 state_dict（比如是整个模型的 pickle），"                "或者模型规模不一致（T/S/B 要对应）。"            )    new_state, skipped = {}, []    for k, v in state2d.items():        if k not in sd3:            skipped.append(k)            continue        tgt = sd3[k]        if tuple(v.shape) == tuple(tgt.shape):            new_state[k] = v        elif v.dim() == 4 and tgt.dim() == 5:  # Conv2d -> Conv3d            kd = tgt.shape[2]            v3 = v.unsqueeze(2)            if kd == 1:                new_state[k] = v3            elif mode == "center":                w = torch.zeros_like(tgt)                w[:, :, kd // 2] = v                new_state[k] = w            else:  # repeat                new_state[k] = v3.repeat(1, 1, kd, 1, 1) / kd        elif v.dim() == 1 and tgt.dim() == 1 and v.shape[0] == tgt.shape[0]:            new_state[k] = v        else:            skipped.append(k)    missing = [k for k in sd3 if k not in new_state]    model3d.load_state_dict(new_state, strict=False)    if verbose:        print(f"[inflate] 从 2D 权重载入 {len(new_state)} 项 | 3D 侧仍缺 {len(missing)} 项 "              f"| 2D 侧多余 {len(skipped)} 项")        if missing[:5]:            print(f"          缺失示例: {missing[:5]}")    return model3ddef check_weights(model: nn.Module) -> list:    """检查参数/BN buffer 里有没有 NaN / Inf，返回问题项的名字列表。"""    bad = []    for name, tensor in list(model.named_parameters()) + list(model.named_buffers()):        if tensor is not None and not torch.isfinite(tensor).all():            n_nan = int(torch.isnan(tensor).sum())            n_inf = int(torch.isinf(tensor).sum())            bad.append(f"{name} (nan={n_nan}, inf={n_inf})")    return baddef trace_nan(model: nn.Module, *inputs, max_frames: int = 3) -> list:    """跑一遍前向，按执行顺序找出**最早**产生 NaN/Inf 的模块。    返回形如 ``["encoder.stage1.0.conv_local (ConvNormAct): out has nan=…, |out|max=…"]`` 的列表。    用于定位"loss 直接 nan"是权重本身坏了，还是某一层数值炸了。    """    hits, handles = [], []    class _Stop(Exception):        pass    named = dict(model.named_modules())    def make_hook(name):        def hook(module, inp, out):            t = out[0] if isinstance(out, (tuple, list)) else out            if torch.is_tensor(t) and t.is_floating_point() and not torch.isfinite(t).all():                hits.append(                    f"{name} ({type(module).__name__}): nan={int(torch.isnan(t).sum())}, "                    f"inf={int(torch.isinf(t).sum())}, |out|max={t.abs().nan_to_num().max().item():.3e}"                )                if len(hits) >= max_frames:                    raise _Stop        return hook    for name, m in named.items():        handles.append(m.register_forward_hook(make_hook(name)))    was_training = model.training    model.eval()    try:        with torch.no_grad():            model(*inputs)    except _Stop:        pass    finally:        for h in handles:            h.remove()        model.train(was_training)    return hitsif __name__ == "__main__":    net = RWKV_UNet3D(1, 1, (128, 128, 128), None, depth_mode="tri")    in1 = torch.rand((1, 1, 128, 128, 128))    out = net(in1)    for i in range(len(out)):        print(out[i].size())